    }
  }
  for (const step of run.steps.filter(step => step.status === 'failed')) entries.push({ kind: 'step', at: step.finished_at || run.finished_at || run.created_at, step });
  return { run, entries: entries.sort((a, b) => a.at.localeCompare(b.at)) };
