def _counts(rows):
    groups = defaultdict(list)
    for row in rows:
        groups[str(row.get("id", ""))].append(row)
    unique = duplicate = conflicting = conflict_ids = 0
    for group in groups.values():
        signatures = {operation_fingerprint(row) for row in group}
        if len(signatures) == 1:
